# ----------------------------------------------------------------------------------
# 1. DATA
# ----------------------------------------------------------------------------------
def load_data(path=None):
    df, src = None, None
    if path and os.path.exists(path):
        df, src = pd.read_csv(path, header=None if _no_header(path) else 0), path
    else:
        for u in DATA_URLS:
            try:
                raw = urllib.request.urlopen(u, timeout=30).read().decode()
                tmp = io.StringIO(raw)
                first = raw.splitlines()[0]
                df = pd.read_csv(tmp, header=None if first[0].isdigit() else 0)
                src = u
                break
            except Exception as e:  # noqa
                print("could not fetch", u, "->", e)
    if df is None:
        raise SystemExit("No dataset found. Pass the path to diabetes.csv (Pima Indians Diabetes Database).")
    if list(df.columns)[:2] == [0, 1]:
        df.columns = FEATURES + ["Outcome"]
    df.columns = [c.strip() for c in df.columns]
    missing = [c for c in FEATURES + ["Outcome"] if c not in df.columns]
    if missing:
        raise SystemExit(f"Dataset is missing expected columns: {missing}")
    return df[FEATURES + ["Outcome"]].copy(), src


def _no_header(path):
    with open(path) as f:
        return f.readline().strip()[:1].isdigit()

