# 2. EXPERIMENT
# ----------------------------------------------------------------------------------
def make_models():
    def pipe(clf):
        return Pipeline([("imp", SimpleImputer(strategy="median")), ("sc", StandardScaler()), ("clf", clf)])
    return {
        "Logistic Regression": (pipe(LogisticRegression(max_iter=2000, class_weight="balanced", random_state=SEED)),
                                {"clf__C": [0.01, 0.1, 1, 10]}),
        "K-Nearest Neighbors": (pipe(KNeighborsClassifier()),
                                {"clf__n_neighbors": [3, 5, 7, 9, 11, 15], "clf__weights": ["uniform", "distance"]}),
        "Support Vector Machine": (pipe(SVC(kernel="rbf", probability=True, class_weight="balanced", random_state=SEED)),
                                   {"clf__C": [0.1, 1, 10], "clf__gamma": ["scale", 0.01, 0.1]}),
        "Random Forest": (pipe(RandomForestClassifier(class_weight="balanced", random_state=SEED, n_jobs=-1)),
                          {"clf__n_estimators": [200, 500], "clf__max_depth": [None, 4, 6, 8],
                           "clf__min_samples_leaf": [1, 3, 5]}),
        "Gradient Boosting": (pipe(GradientBoostingClassifier(random_state=SEED)),
                              {"clf__n_estimators": [100, 200], "clf__learning_rate": [0.03, 0.1],
                               "clf__max_depth": [2, 3]}),
    }


def run_experiment(df, outdir):
    R = {}
    d = df.copy()
    zero_counts = {c: int((d[c] == 0).sum()) for c in ZERO_INVALID}
    d[ZERO_INVALID] = d[ZERO_INVALID].replace(0, np.nan)
    X, y = d[FEATURES], d["Outcome"].astype(int)
    R["dataset"] = dict(n=len(d), n_features=len(FEATURES), n_pos=int(y.sum()), n_neg=int((1 - y).sum()),
                        prevalence=float(y.mean()), zero_counts=zero_counts,
                        missing_total=int(d[ZERO_INVALID].isna().sum().sum()), duplicates=int(df.duplicated().sum()))
    Xtr, Xte, ytr, yte = train_test_split(X, y, test_size=0.20, stratify=y, random_state=SEED)
    R["split"] = dict(n_train=len(Xtr), n_test=len(Xte), test_pos=int(yte.sum()), train_pos=int(ytr.sum()),
                      majority_baseline=float(max(yte.mean(), 1 - yte.mean())))
    cv = StratifiedKFold(5, shuffle=True, random_state=SEED)

    # descriptive table
    rows = []
    for c in FEATURES:
        a, b = d.loc[y == 0, c].dropna(), d.loc[y == 1, c].dropna()
        p = mannwhitneyu(a, b).pvalue
        rows.append(dict(Feature=NICE[c], Missing_zero_values=zero_counts.get(c, 0),
                         Non_diabetic=f"{a.mean():.1f} ± {a.std():.1f}", Diabetic=f"{b.mean():.1f} ± {b.std():.1f}",
                         p_value=p))
    R["table1"] = rows

    # models
    R["models"], fitted = {}, {}
    for name, (pipe, grid) in make_models().items():
        print("tuning", name, "...")
        gs = GridSearchCV(pipe, grid, scoring="roc_auc", cv=cv, n_jobs=-1, refit=True)
        gs.fit(Xtr, ytr)
        best = gs.best_estimator_
        i = gs.best_index_
        cv_acc = cross_val_score(best, Xtr, ytr, cv=cv, scoring="accuracy")
        prob = best.predict_proba(Xte)[:, 1]
        pred = (prob >= 0.5).astype(int)
        tn, fp, fn, tp = confusion_matrix(yte, pred).ravel()
        fpr, tpr, _ = roc_curve(yte, prob)
        R["models"][name] = dict(
            best_params={k.replace("clf__", ""): v for k, v in gs.best_params_.items()},
            grid={k.replace("clf__", ""): [str(v) for v in vals] for k, vals in grid.items()},
            cv_auc=float(gs.best_score_), cv_auc_sd=float(gs.cv_results_["std_test_score"][i]),
            cv_acc=float(cv_acc.mean()), cv_acc_sd=float(cv_acc.std()),
            accuracy=accuracy_score(yte, pred), precision=precision_score(yte, pred, zero_division=0),
            recall=recall_score(yte, pred), specificity=tn / (tn + fp), f1=f1_score(yte, pred),
            auc=roc_auc_score(yte, prob), mcc=matthews_corrcoef(yte, pred),
            cm=[[int(tn), int(fp)], [int(fn), int(tp)]], fpr=fpr.tolist(), tpr=tpr.tolist())
        fitted[name] = best
        R["models"][name]["_prob"] = prob
    best_name = max(R["models"], key=lambda k: R["models"][k]["cv_auc"])   # selected on CV, NOT on test
    R["best"] = best_name
    # bootstrap CI of best model on test set
    rng = np.random.default_rng(SEED)
    prob, yt = R["models"][best_name]["_prob"], yte.values
    accs, aucs = [], []
    for _ in range(1000):
        idx = rng.integers(0, len(yt), len(yt))
        if len(np.unique(yt[idx])) < 2:
            continue
        accs.append(accuracy_score(yt[idx], prob[idx] >= 0.5)); aucs.append(roc_auc_score(yt[idx], prob[idx]))
    R["best_ci"] = dict(acc=[float(np.percentile(accs, 2.5)), float(np.percentile(accs, 97.5))],
                        auc=[float(np.percentile(aucs, 2.5)), float(np.percentile(aucs, 97.5))])
    # importance
    pi = permutation_importance(fitted[best_name], Xte, yte, scoring="roc_auc", n_repeats=30, random_state=SEED)
    R["perm"] = {f: (float(m), float(s)) for f, m, s in zip(FEATURES, pi.importances_mean, pi.importances_std)}
    if "Random Forest" in fitted:
        rf = fitted["Random Forest"].named_steps["clf"]
        R["rf_imp"] = {f: float(v) for f, v in zip(FEATURES, rf.feature_importances_)}
    R["versions"] = dict(python=sys.version.split()[0], sklearn=sklearn.__version__, pandas=pd.__version__,
                         numpy=np.__version__)
    make_figures(d, y, R, yte, outdir)
    return R

