def make_figures(d, y, R, yte, outdir):
    os.makedirs(outdir, exist_ok=True)
    plt.rcParams.update({"font.size": 10, "axes.spines.top": False, "axes.spines.right": False,
                         "figure.dpi": 120, "savefig.dpi": 300})
    # Fig1 class balance + feature distributions
    fig, ax = plt.subplots(2, 4, figsize=(11, 5.6))
    for a, c in zip(ax.ravel(), FEATURES):
        for lab, col in [(0, BLUE), (1, ORANGE)]:
            a.hist(d.loc[y == lab, c].dropna(), bins=20, alpha=.6, color=col, label=["Non-diabetic", "Diabetic"][lab])
        a.set_title(NICE[c], fontsize=9)
    ax[0, 0].legend(fontsize=8, frameon=False)
    fig.suptitle(f"Feature distributions by class (n = {R['dataset']['n']}; "
                 f"{R['dataset']['n_pos']} diabetic, {R['dataset']['n_neg']} non-diabetic)", y=1.0)
    fig.tight_layout(); fig.savefig(f"{outdir}/fig1_distributions.png"); plt.close(fig)
    # Fig2 correlation
    fig, a = plt.subplots(figsize=(6.6, 5.4))
    corr = d.rename(columns=NICE).rename(columns={"Outcome": "Outcome"}).corr(method="spearman")
    sns.heatmap(corr, annot=True, fmt=".2f", cmap="RdBu_r", center=0, vmin=-1, vmax=1, ax=a, cbar_kws={"shrink": .8},
                annot_kws={"size": 7})
    fig.tight_layout(); fig.savefig(f"{outdir}/fig2_correlation.png"); plt.close(fig)
    # Fig3 ROC
    fig, a = plt.subplots(figsize=(5.6, 5))
    pal = [BLUE, ORANGE, "#3a9d6e", "#8b5cf6", "#c2410c"]
    for (n, m), col in zip(R["models"].items(), pal):
        a.plot(m["fpr"], m["tpr"], color=col, lw=1.8, label=f"{n} (AUC {m['auc']:.3f})")
    a.plot([0, 1], [0, 1], "--", color=GREY, lw=1)
    a.set_xlabel("False positive rate"); a.set_ylabel("True positive rate"); a.legend(frameon=False, fontsize=8, loc="lower right")
    fig.tight_layout(); fig.savefig(f"{outdir}/fig3_roc.png"); plt.close(fig)
    # Fig4 confusion matrices
    fig, ax = plt.subplots(1, 5, figsize=(14, 3.1))
    for a, (n, m) in zip(ax, R["models"].items()):
        sns.heatmap(np.array(m["cm"]), annot=True, fmt="d", cmap="Blues", cbar=False, ax=a,
                    xticklabels=["Non-diab.", "Diabetic"], yticklabels=["Non-diab.", "Diabetic"])
        a.set_title(n, fontsize=9); a.set_xlabel("Predicted"); a.set_ylabel("Actual")
    fig.tight_layout(); fig.savefig(f"{outdir}/fig4_confusion.png"); plt.close(fig)
    # Fig5 importance
    fig, ax = plt.subplots(1, 2 if "rf_imp" in R else 1, figsize=(10 if "rf_imp" in R else 5.5, 4))
    ax = np.atleast_1d(ax)
    p = sorted(R["perm"].items(), key=lambda kv: kv[1][0])
    ax[0].barh([NICE[k] for k, _ in p], [v[0] for _, v in p], xerr=[v[1] for _, v in p], color=BLUE)
    ax[0].set_xlabel("Permutation importance (drop in test AUC)"); ax[0].set_title(f"{R['best']}", fontsize=10)
    if "rf_imp" in R:
        q = sorted(R["rf_imp"].items(), key=lambda kv: kv[1])
        ax[1].barh([NICE[k] for k, _ in q], [v for _, v in q], color=ORANGE)
        ax[1].set_xlabel("Impurity-based importance"); ax[1].set_title("Random Forest", fontsize=10)
    fig.tight_layout(); fig.savefig(f"{outdir}/fig5_importance.png"); plt.close(fig)
    # Fig6 comparison
    fig, a = plt.subplots(figsize=(8, 4))
    names = list(R["models"]); w = 0.2
    for j, (k, lab, col) in enumerate([("accuracy", "Accuracy", BLUE), ("f1", "F1", ORANGE),
                                       ("auc", "ROC-AUC", "#3a9d6e"), ("recall", "Recall", "#8b5cf6")]):
        a.bar(np.arange(len(names)) + (j - 1.5) * w, [R["models"][n][k] for n in names], w, label=lab, color=col)
    a.set_xticks(np.arange(len(names))); a.set_xticklabels([n.replace(" ", "\n", 1) for n in names], fontsize=8)
    a.set_ylim(0.4, 1.0); a.legend(frameon=False, ncol=4, fontsize=8); a.set_ylabel("Test-set score")
    fig.tight_layout(); fig.savefig(f"{outdir}/fig6_comparison.png"); plt.close(fig)

