from docx import Document
from docx.shared import Pt, Inches
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml.ns import qn
from docx.oxml import OxmlElement

def set_text(p, text):
    for r in p.runs[1:]:
        r._element.getparent().remove(r._element)
    if p.runs:
        p.runs[0].text = text
    else:
        p.add_run(text)

def insert_after(p, text="", like=None):
    new = copy.deepcopy((like or p)._element)
    p._element.addnext(new)
    from docx.text.paragraph import Paragraph
    np_ = Paragraph(new, p._parent)
    for r in np_.runs[1:]:
        r._element.getparent().remove(r._element)
    if np_.runs:
        np_.runs[0].text = text
    else:
        np_.add_run(text)
    return np_

def fill_body(p, texts):
    set_text(p, texts[0]); last = p
    for t in texts[1:]:
        last = insert_after(last, t, like=p)
    return last

def border_table(tbl):
    tblPr = tbl._tbl.tblPr
    b = OxmlElement("w:tblBorders")
    for edge in ("top", "bottom", "insideH"):
        e = OxmlElement(f"w:{edge}"); e.set(qn("w:val"), "single"); e.set(qn("w:sz"), "6"); e.set(qn("w:color"), "444444"); b.append(e)
    tblPr.append(b)

def add_table_after(doc, anchor, header, rows, widths=None, size=8.5):
    tbl = doc.add_table(rows=1, cols=len(header))
    border_table(tbl)
    for i, h in enumerate(header):
        c = tbl.rows[0].cells[i]; c.text = ""
        r = c.paragraphs[0].add_run(h); r.bold = True; r.font.size = Pt(size)
    for row in rows:
        cells = tbl.add_row().cells
        for i, v in enumerate(row):
            cells[i].text = ""
            cells[i].paragraphs[0].add_run(str(v)).font.size = Pt(size)
    anchor._element.addnext(tbl._tbl)
    from docx.text.paragraph import Paragraph
    sp = OxmlElement("w:p"); tbl._tbl.addnext(sp)
    return Paragraph(sp, anchor._parent)

def build_docx(R, T, C, template, outdir, figdir):
    doc = Document(template)
    P = list(doc.paragraphs)
    # title / authors
    set_text(P[0], C["title"])
    a = P[1]
    for r in list(a.runs): r._element.getparent().remove(r._element)
    n = len(C["authors"])
    for i, name in enumerate(C["authors"]):
        a.add_run(name); s = a.add_run("1" + ("," if i == n - 1 else "")); s.font.superscript = True
        if i == n - 1:
            s.text = "1"
            a.add_run(",*").font.superscript = False
        elif i < n - 1:
            a.add_run(", ")
    aff = P[2]
    for r in list(aff.runs): r._element.getparent().remove(r._element)
    s = aff.add_run("1"); s.font.superscript = True
    aff.add_run(" " + C["affiliation"]).add_break()
    aff.add_run("*Corresponding author: " + C["corresponding_email"])
    P[3]._element.getparent().remove(P[3]._element)       # template instruction note
    # highlights, abstract, keywords
    fill_body(P[5], ["• " + h for h in T["highlights"]])
    fill_body(P[7], [T["abstract"]])
    fill_body(P[9], [T["keywords"]])
    fill_body(P[11], T["intro"])
    fill_body(P[13], [T["m_intro"]])
    fill_body(P[15], T["m_data"])
    fill_body(P[17], T["m_model"])
    fill_body(P[19], T["m_eval"])
    fill_body(P[21], T["results"])
    fill_body(P[23], T["discussion"])
    fill_body(P[25], T["conclusion"])
    fill_body(P[27], [T["credit"]])
    fill_body(P[29], [C["funding"]])
    fill_body(P[31], [C["competing"]])
    fill_body(P[33], [T["data"]])
    fill_body(P[35], [T["ethics"]])
    fill_body(P[37], [T["ack"]])
    fill_body(P[39], [f"[{i}] {r}" for i, r in enumerate(REFS, 1)])

    M = R["models"]
    # ---- tables ----
    anchor = P[41]; set_text(anchor, "Table 1. Characteristics of the predictors by diabetes status (mean ± SD; zeros in glucose, blood pressure, skin thickness, insulin and BMI treated as missing).")
    rows = [[r["Feature"], r["Missing_zero_values"], r["Non_diabetic"], r["Diabetic"],
             "<0.001" if r["p_value"] < 0.001 else f"{r['p_value']:.3f}"] for r in R["table1"]]
    nxt = add_table_after(doc, anchor, ["Feature", "Invalid zeros (n)", "Non-diabetic", "Diabetic", "p (Mann–Whitney)"], rows)
    set_text(nxt, "Table 2. Hyperparameter search grids and values selected by five-fold cross-validation on the training set.")
    rows = [[n, "; ".join(f"{k}: {', '.join(v)}" for k, v in m["grid"].items()),
             "; ".join(f"{k}={v}" for k, v in m["best_params"].items()), f3(m["cv_auc"]) + " ± " + f3(m["cv_auc_sd"])]
            for n, m in M.items()]
    nxt = add_table_after(doc, nxt, ["Model", "Search grid", "Selected", "CV AUC (mean ± SD)"], rows, size=8)
    set_text(nxt, "Table 3. Performance of the five classifiers on the held-out test set (threshold 0.5). The model selected by cross-validation is marked with an asterisk.")
    rows = [[n + (" *" if n == R["best"] else ""), pc(m["accuracy"]), f3(m["precision"]), f3(m["recall"]), f3(m["specificity"]),
             f3(m["f1"]), f3(m["mcc"]), f3(m["auc"])] for n, m in M.items()]
    nxt = add_table_after(doc, nxt, ["Model", "Accuracy", "Precision", "Recall", "Specificity", "F1", "MCC", "AUC"], rows)
    set_text(nxt, "Table 4. Results reported in the reviewed literature (as published; datasets and protocols differ, so values are indicative only).")
    lit = [
        ["Rahman et al. [2]", "Pima Indians (8 → 5 features)", "Boruta + LightGBM", "Accuracy 85.16%; F1 0.8541"],
        ["Nguyen & Zhang [7]", "BRFSS 2015 survey (21 features)", "Decision tree / KNN / Logistic regression", "Accuracy 74% / 72% / 75%"],
        ["Nipa et al. [4]", "Sylhet Diabetes Hospital (UCI) + Bangladesh questionnaire", "35 classifiers compared", "Best accuracy 97.11% (Sylhet data)"],
        ["Fazakis et al. [5]", "English Longitudinal Study of Ageing", "WeightedVotingLRRFs ensemble", "AUC 0.884"],
        ["Matboli et al. [6]", "Molecular + biochemical markers (4-class)", "Extra Trees", "AUC 0.9985"],
        ["This study", f"Pima Indians ({R['dataset']['n']} records, 8 features)", R["best"], f"Accuracy {pc(M[R['best']]['accuracy'])}; AUC {f3(M[R['best']]['auc'])}"],
    ]
    nxt = add_table_after(doc, nxt, ["Study", "Data", "Best model", "Reported result"], lit)
    # ---- figures ----
    caps = [
        ("fig1_distributions.png", "Fig. 1. Distribution of each predictor in diabetic (orange) and non-diabetic (blue) women. Invalid zeros were treated as missing."),
        ("fig2_correlation.png", "Fig. 2. Spearman correlation matrix of the predictors and the outcome."),
        ("fig3_roc.png", "Fig. 3. Receiver operating characteristic curves of the five classifiers on the test set; AUC = area under the curve. The dashed line is chance."),
        ("fig4_confusion.png", "Fig. 4. Confusion matrices of the five classifiers on the test set (rows: actual class; columns: predicted class)."),
        ("fig5_importance.png", f"Fig. 5. Feature importance. Left: permutation importance (mean decrease in test AUC, ± SD over 30 repeats) for {R['best']}. Right: impurity-based importance for Random Forest."),
        ("fig6_comparison.png", "Fig. 6. Comparison of accuracy, F1-score, ROC-AUC and recall of the five classifiers on the test set."),
    ]
    fp = P[43]
    last = fp
    set_text(fp, caps[0][1])
    # picture before first caption: put picture paragraphs before each caption
    def pic_before(par, fn):
        pp = insert_after(par, "", like=par)
        # move pp before par
        par._element.addprevious(pp._element)
        for r in list(pp.runs): r._element.getparent().remove(r._element)
        pp.alignment = WD_ALIGN_PARAGRAPH.CENTER
        pp.add_run().add_picture(os.path.join(figdir, fn), width=Inches(6.2 if fn != "fig4_confusion.png" else 6.5))
    pic_before(fp, caps[0][0]); last = fp
    for fn, cap in caps[1:]:
        last = insert_after(last, cap, like=fp)
        pic_before(last, fn)
    # P[43] may contain a 2nd template run line -> set_text already collapsed runs
    fill_body(P[45], [
        "Supplementary file S1: Jupyter notebook / Python script (diabetes_pipeline.py) used to generate every result.",
        "Supplementary file S2: results.json and CSV tables with all metrics, confusion matrices and selected hyperparameters.",
        "Supplementary file S3: high-resolution figures (PNG, 300 dpi).",
    ])
    path = os.path.join(outdir, "Manuscript_Diabetes_Prediction_ML.docx")
    doc.save(path)
    return path

# ----------------------------------------------------------------------------------
def main(data_path=None, template=None, outdir="outputs", config=None):
    C = dict(DEFAULT_CONFIG); C.update(config or {})
    os.makedirs(outdir, exist_ok=True)
    df, src = load_data(data_path)
    print("data source:", src, df.shape)
    df.to_csv(os.path.join(outdir, "diabetes_data_used.csv"), index=False)
    R = run_experiment(df, outdir)
    T = compose(R, C)
    docx_path = build_docx(R, T, C, template, outdir, outdir)
    clean = {k: v for k, v in R.items()}
    clean["models"] = {n: {k: v for k, v in m.items() if k != "_prob"} for n, m in R["models"].items()}
    clean["data_source"] = src
    json.dump(clean, open(os.path.join(outdir, "results.json"), "w"), indent=2, default=float)
    pd.DataFrame([{ "Model": n, **{k: m[k] for k in ["accuracy", "precision", "recall", "specificity", "f1", "mcc", "auc", "cv_auc", "cv_auc_sd", "cv_acc"]}}
                  for n, m in R["models"].items()]).to_csv(os.path.join(outdir, "table3_test_performance.csv"), index=False)
    print("\nDONE ->", docx_path)
    for n, m in R["models"].items():
        print(f"{n:24s} acc={m['accuracy']:.3f} f1={m['f1']:.3f} auc={m['auc']:.3f} cvAUC={m['cv_auc']:.3f}")
    print("best (by CV):", R["best"])
    return R, docx_path


if False:
    a = sys.argv
    main(a[1] if len(a) > 1 else None, a[2] if len(a) > 2 else "template.docx", a[3] if len(a) > 3 else "outputs")

